return {["fb36_01"]={["down"]=[[fb36_04]],["dsc"]=[[这里是书院的讲堂，窗明几净，一尘不染。一张古意盎然的书案上摆着几本翻开了的线装书籍。紧靠墙壁有一个书架讲堂内多历代楹联石刻，足见书院历史的悠久。值得一提的是嵌在讲堂前左壁的学规。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_01]],["name"]=[[书院]],["permission"]=2,["role1"]=[[fb36r01_1]],["role2"]=[[fb36r01_2]],["stepMusic"]=[[jiaobu]]},["fb36_02"]={["down"]=[[fb36_07]],["dsc"]=[[这里是安定门，城门正上方刻着“安定门”三个大字，城墙上贴着几张官府告示。几个官兵守在两旁…]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_02]],["name"]=[[安定门]],["permission"]=2,["role1"]=[[fb36r02_1]],["role2"]=[[fb36r02_2]],["role3"]=[[liangongnpc4a]],["stepMusic"]=[[jiaobu]]},["fb36_03"]={["down"]=[[fb36_09]],["dsc"]=[[这里便是平王府。平王府修建的气势磅礴，阁楼之上不加任何装饰，只是以乌漆随意刷就，倒显得大气简约。整个王府人影憧憧，到处都是铁甲军士来回巡逻，肃杀之气甚重。仔细观察这些军士，只见他们身披重甲却步履稳重，身上散发着浓郁的杀气，似乎都是沙场上身经百战的死士。]],["id"]=[[fb36_03]],["name"]=[[平王府]],["permission"]=2,["right"]=[[fb36_53]],["role1"]=[[fb36r03_1]],["role2"]=[[fb36r03_2]],["role3"]=[[fb36r03_3]],["stepMusic"]=[[jiaobu]]},["fb36_04"]={["down"]=[[fb36_13]],["dsc"]=[[这里是西四北大街。南边通往西单。东边通向朱雀门，北面是一间书院。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_04]],["item1"]=[[fb36item40]],["name"]=[[西四北大街]],["permission"]=2,["right"]=[[fb36_05]],["role1"]=[[fb36r04_1]],["role2"]=[[fb36r04_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_01]]},["fb36_05"]={["down"]=[[fb36_10]],["dsc"]=[[这是一条东西走向的大道。东边通往朱雀门。西边通往西四北大街。南边便是顺天府了，一般人都不敢往那儿去。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_05]],["left"]=[[fb36_04]],["name"]=[[朱雀街]],["permission"]=2,["right"]=[[fb36_06]],["role1"]=[[fb36r05_1]],["role2"]=[[fb36r05_2]],["stepMusic"]=[[jiaobu]]},["fb36_06"]={["dsc"]=[[这是一条东西走向的大道。东边通往朱雀门。西边通往西四北大街。不知道为什么，这里总是冷冷清清，见不到几个行人。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_06]],["left"]=[[fb36_05]],["name"]=[[朱雀街]],["permission"]=2,["right"]=[[fb36_07]],["role1"]=[[fb36r06_1]],["role2"]=[[fb36r06_2]],["role3"]=[[fb36r06_3]],["role4"]=[[fb36r06_4]],["stepMusic"]=[[jiaobu]]},["fb36_07"]={["down"]=[[fb36_11]],["dsc"]=[[这里就是朱雀门广场，灰色的城墙给人以庄严肃穆之感，再往南就是皇宫后门。门前有座小桥，一条护城河绕城而过。越过小桥向南望去，皇宫的轮廓益发显得雄伟高大。一条笔直的大道横贯东西，东边是青龙街，西边是朱雀门西街。北边通往安定门。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_07]],["left"]=[[fb36_06]],["name"]=[[朱雀门]],["permission"]=2,["right"]=[[fb36_08]],["role1"]=[[fb36r07_1]],["role2"]=[[fb36r07_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_02]]},["fb36_08"]={["down"]=[[fb36_12]],["dsc"]=[[这是一条东西走向的大道。西边通往朱雀门。东边通往青龙正街。南边就是官府都统陆千侯的府邸了，一般人都不敢往那儿去。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_08]],["item1"]=[[fb36r08_5]],["left"]=[[fb36_07]],["name"]=[[青龙街]],["permission"]=2,["right"]=[[fb36_09]],["role1"]=[[fb36r08_1]],["role2"]=[[fb36r08_2]],["role3"]=[[fb36r08_3]],["role4"]=[[fb36r08_4]],["stepMusic"]=[[jiaobu]]},["fb36_09"]={["down"]=[[fb36_16]],["dsc"]=[[这里是青龙大街的尽头。北边是一座富丽堂皇的大楼，门额上悬挂一方横匾，写着“平王府”三个大字。西边通往朱雀门。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_09]],["left"]=[[fb36_08]],["name"]=[[青龙正街]],["permission"]=2,["role1"]=[[fb36r09_1]],["role2"]=[[fb36r09_2]],["role3"]=[[fb36r09_3]],["role4"]=[[fb36r09_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_03]]},["fb36_10"]={["dsc"]=[[这里是顺天府，是京城的管理者顺天府尹所在的地方。一眼望去，朱门半掩，府内寂静无声，门口左右各立着一尊石狮，庄严肃穆，令人心生畏惧。]],["id"]=[[fb36_10]],["name"]=[[顺天府]],["permission"]=2,["role1"]=[[fb36r10_1]],["role2"]=[[fb36r10_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_05]]},["fb36_11"]={["dsc"]=[[这是一座破旧的石桥，桥下是护城河，缓缓的流水，水看上去很清。这里是进皇宫后门的必经之路。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_11]],["name"]=[[小桥]],["permission"]=2,["role1"]=[[fb36r11_1]],["role2"]=[[fb36r11_2]],["role3"]=[[liangongnpc5a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_07]]},["fb36_12"]={["dsc"]=[[这是官府统领陆千侯的宅邸。看起来与一般达官贵人的宅邸无异。只是御赐的匾额格外亮眼，两名崇武卫守在门口。]],["id"]=[[fb36_12]],["name"]=[[陆千侯府]],["permission"]=2,["role1"]=[[fb36r12_1]],["role2"]=[[fb36r12_2]],["role3"]=[[liangongnpc3a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_08]]},["fb36_13"]={["down"]=[[fb36_19]],["dsc"]=[[这是一条长长的街道。东边就是游人们常去的文庙，那里长年香火不断，烟雾缭绕。南边是西单北大街。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_13]],["name"]=[[西四北大街]],["permission"]=2,["right"]=[[fb36_14]],["role1"]=[[fb36r13_1]],["role2"]=[[fb36r13_2]],["role3"]=[[fb36r13_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_04]]},["fb36_14"]={["dsc"]=[[这里是文庙正殿，内有孔夫子像。历代皇帝都懂得利用儒教思想来巩固自己的江山社稷，当朝皇帝自然也不例外。不论何人到此，都毕恭毕敬地上香礼拜。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_14]],["left"]=[[fb36_13]],["name"]=[[文庙]],["permission"]=2,["role1"]=[[fb36r14_1]],["stepMusic"]=[[jiaobu]]},["fb36_15"]={["dsc"]=[[方圆数百里内提起旺德楼可以说是无人不知，无人不晓。楼下布置简易，顾客多是匆匆的行人，买点包子、鸡腿、米酒就赶路去了。楼上是雅座。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_15]],["name"]=[[旺德楼]],["permission"]=1,["right"]=[[fb36_16]],["role1"]=[[fb36r15_1]],["role2"]=[[fb36r15_2]],["stepMusic"]=[[jiaobu]]},["fb36_16"]={["down"]=[[fb36_23]],["dsc"]=[[这是一条宽阔的青石街道，向南北两头延伸。南边北边都是长长的街道，西边是著名的“旺德楼”酒楼，东边通往朝阳门。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_16]],["left"]=[[fb36_15]],["name"]=[[青龙正街]],["permission"]=1,["right"]=[[fb36_17]],["role1"]=[[fb36r16_1]],["role2"]=[[fb36r16_2]],["role3"]=[[fb36r16_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_09]]},["fb36_17"]={["dsc"]=[[这是一条东西走向的大道。西边人声鼎沸，十分热闹。东边就是朝阳门。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_17]],["left"]=[[fb36_16]],["name"]=[[朝阳路]],["permission"]=1,["right"]=[[fb36_18]],["role1"]=[[fb36r17_1]],["role2"]=[[fb36r17_2]],["role3"]=[[fb36r17_3]],["stepMusic"]=[[jiaobu]]},["fb36_18"]={["dsc"]=[[这里就是朝阳门，城墙上刻着“朝阳门”三个大字。东门就在东南边，那里人来车往，是进出京城的要道，盘查十分严密。一条宽阔的大道向西延伸，通往著名的青龙大街。从这里也可以出京城，东北边就是郊外，那里有一大片竹林，一个人也看不见。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_18]],["left"]=[[fb36_17]],["name"]=[[朝阳门]],["permission"]=1,["role1"]=[[fb36r18_1]],["role2"]=[[fb36r18_2]],["stepMusic"]=[[jiaobu]]},["fb36_19"]={["down"]=[[fb36_26]],["dsc"]=[[这里是西单北大街。东边有一家很大的赌场，里面闹哄哄的。北边是西四北大街。南边就是西单了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_19]],["name"]=[[西单北大街]],["permission"]=2,["right"]=[[fb36_20]],["role1"]=[[fb36r19_1]],["role2"]=[[fb36r19_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_13]]},["fb36_20"]={["dsc"]=[[这里是赌「大小」的房间，墙上挂着一块牌子。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_20]],["item1"]=[[fb36item13]],["item2"]=[[fb36r20_5]],["left"]=[[fb36_19]],["name"]=[[赌场]],["permission"]=2,["role1"]=[[fb36r20_1]],["role2"]=[[fb36r20_2]],["role3"]=[[fb36r20_3]],["role4"]=[[fb36r20_4]],["stepMusic"]=[[jiaobu]]},["fb36_21"]={["down"]=[[fb36_28]],["dsc"]=[[白虎门便是皇宫正门。巍峨雄伟的城墙上，飞檐楼对每个华夏子民都是十分熟悉的形状，气势十分辉煌，不愧是泱泱大国。一张镶金边的告示贴在墙上，许多官兵立在两旁。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_21]],["name"]=[[皇宫]],["permission"]=2,["role1"]=[[fb36r21_1]],["role2"]=[[fb36r21_2]],["stepMusic"]=[[jiaobu]]},["fb36_22"]={["dsc"]=[[这座颇有江南园林般别雅景致的大院便是福王府了。远远望去，叠山造石，鸟语花香，亭台楼阁与花草树木星罗棋布，到处是叫不上名字的珍稀花草。王府门口飞檐凌空，中间一块巨大的御赐牌匾上烫金的字写着“福王府”。]],["id"]=[[fb36_22]],["name"]=[[福王府]],["permission"]=2,["right"]=[[fb36_23]],["role1"]=[[fb36r22_1]],["role2"]=[[fb36r22_2]],["role3"]=[[liangongnpc2a]],["stepMusic"]=[[jiaobu]]},["fb36_23"]={["down"]=[[fb36_34]],["dsc"]=[[你走在一条繁忙的街道上，车水马龙，人来人往。许多人都从南边走来，那里是玄武街。西边是一条宽阔的街道，不知为何却十分冷清。东边是一家钱庄，可以听到叮叮当当的金银声音。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_23]],["item1"]=[[fb36item49]],["left"]=[[fb36_22]],["name"]=[[青龙正街]],["permission"]=2,["right"]=[[fb36_24]],["role1"]=[[fb36r23_1]],["role2"]=[[fb36r23_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_16]]},["fb36_24"]={["dsc"]=[[这是一家老字号的钱庄，已有几百年的历史，在全国各地都有分店。它发行的银票信誉非常好，通行全国。不管你走到哪里，在任何一个本庄分店都可以任意存取。墙上挂着一个牌子。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_24]],["item1"]=[[fb36item33]],["item2"]=[[fb36item34]],["item3"]=[[fb36item35]],["left"]=[[fb36_23]],["name"]=[[钱庄]],["permission"]=2,["role1"]=[[fb36r24_1]],["role2"]=[[fb36item30]],["role3"]=[[fb36item31]],["role4"]=[[fb36item32]],["stepMusic"]=[[jiaobu]]},["fb36_25"]={["dsc"]=[[这是一家杂货铺，大箱小箱堆满了一地，都是一些日常用品。胡掌柜懒洋洋地躺在一只躺椅上，招呼着过往行人。据说私底下他也卖一些贵重的东西。摊上立着一块招牌。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_25]],["name"]=[[杂货店]],["permission"]=2,["right"]=[[fb36_26]],["role1"]=[[fb36r25_1]],["stepMusic"]=[[jiaobu]]},["fb36_26"]={["down"]=[[fb36_31]],["dsc"]=[[这里就是西单，人来人往，十分热闹。游人虽然多，但大都只四处晃悠，东瞅瞅西看看，也不急着买什么。西边有家杂货铺，去那里买东西的人很多。不断有人从北边走来，似乎那里也挺热闹。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_26]],["left"]=[[fb36_25]],["name"]=[[西单]],["permission"]=2,["role1"]=[[fb36r26_1]],["role2"]=[[fb36r26_2]],["role3"]=[[liangongnpc1a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_19]]},["fb36_27"]={["down"]=[[fb36_32]],["dsc"]=[[这里是戏台，虽然有些小，但是很干净。一个戏子正在表演。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_27]],["item1"]=[[fb36item7]],["name"]=[[戏院]],["permission"]=1,["role1"]=[[fb36r27_6]],["role2"]=[[lianqinnpc1]],["stepMusic"]=[[jiaobu]]},["fb36_28"]={["down"]=[[fb36_33]],["dsc"]=[[五座金水石桥横卧河上，中间那座桥是专供皇帝使用的，称为“御路桥”，桥的柱头全为龙形，人称“蟠龙柱”。两边为王公桥，桥的柱头雕成“荷花柱”。桥下是缓缓的流水。水看上去很清，据说曾有人在这里跳河。这里是进皇宫正门的必经之路。]],["id"]=[[fb36_28]],["name"]=[[小桥]],["permission"]=2,["role1"]=[[fb36r28_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_21]]},["fb36_29"]={["down"]=[[fb36_35]],["dsc"]=[[你一走进来，便听到几个酒客在那里喝酒畅谈，进进出出的客人展现着生意的兴隆。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_29]],["item1"]=[[fb36item2]],["item2"]=[[fb36item21]],["name"]=[[千金楼]],["permission"]=1,["role1"]=[[fb36r29_1]],["role2"]=[[fb36r29_2]],["role3"]=[[fb36r29_3]],["role4"]=[[fb36r29_4]],["stepMusic"]=[[jiaobu]]},["fb36_30"]={["dsc"]=[[这是西城门，几年前曾经遭到土匪的攻打，因此显得有些破败。城门正上方勉勉强强可以认出“西门”两个大字，城墙上贴着几张通缉告示。罪犯常常从这里逃出京城，官兵们戒备森严，动不动就截住行人盘问。一条笔直的青石板大道向东西两边延伸。西边是郊外，骑马的、坐轿的、走路的，行人匆匆。东边是城里。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_30]],["item1"]=[[fb36item38]],["name"]=[[西门]],["permission"]=2,["right"]=[[fb36_31]],["role1"]=[[fb36r30_1]],["role2"]=[[fb36r30_2]],["stepMusic"]=[[jiaobu]]},["fb36_31"]={["down"]=[[fb36_37]],["dsc"]=[[你走在街上，感到这里的街面要比别处的干净、整洁。再往西就是西城门，直通往郊外。东边是空荡荡的街道。南边是一条行人稀少的小巷，北边通往西单。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_31]],["left"]=[[fb36_30]],["name"]=[[白虎街]],["permission"]=1,["right"]=[[fb36_32]],["role1"]=[[fb36r31_1]],["role2"]=[[liangongnpc6a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_26]]},["fb36_32"]={["down"]=[[fb36_39]],["dsc"]=[[这是一条宽阔的青石板街道，向东西两头延伸。往西望去，长长的街道看不到头。东边就是白虎门。一阵阵喝采声不时从北边的戏院传来。南边就是京城最著名的“回春堂”药店。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_32]],["left"]=[[fb36_31]],["name"]=[[白虎街]],["permission"]=1,["right"]=[[fb36_33]],["role1"]=[[fb36r32_1]],["role2"]=[[fb36r32_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_27]]},["fb36_33"]={["down"]=[[fb36_42]],["dsc"]=[[这里就是白虎门广场，灰色的城墙给人以庄严肃穆之感，再往北就是皇宫了。皇宫正门前有座小桥，一条护城河绕城而过。越过小桥向北望去，皇宫的轮廓益发显得雄伟高大。一条笔直的大道横贯东西，东边是玄武街，西边是白虎街。南边是一条繁华的大道，从那往下有一座天桥，据说游人很多。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_33]],["item1"]=[[fb36item48]],["left"]=[[fb36_32]],["name"]=[[白虎门]],["permission"]=1,["right"]=[[fb36_34]],["role1"]=[[fb36r33_1]],["role2"]=[[fb36r33_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_28]]},["fb36_34"]={["dsc"]=[[这里是玄武街，宽阔的街道上车水马龙，人来人往。由于青龙大街就在北边，许多人都往北去，那里人声鼎沸，似乎十分热闹。西边比这里更热闹，向西走就是白虎门了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_34]],["left"]=[[fb36_33]],["name"]=[[玄武街]],["permission"]=1,["right"]=[[fb36_35]],["role1"]=[[fb36item1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_23]]},["fb36_35"]={["down"]=[[fb36_40]],["dsc"]=[[你走在玄武街上，踩着坚实的青石板地面。东边是东城门，可以听到守城官兵的吆喝声。南边是打铁铺，叮叮当当的声音老远就能听到。北边是京城有名的千金楼。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_35]],["left"]=[[fb36_34]],["name"]=[[玄武街]],["permission"]=1,["right"]=[[fb36_36]],["role1"]=[[fb36r35_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_29]]},["fb36_36"]={["dsc"]=[[这是东城门，城门正上方刻着“东门”两个大字，城墙上贴着几张官府告示。一条笔直的青石板大道向东西两边延伸。东边是郊外，越过城门可以看到驿道上人来车往，尘土飞扬。西边通往城里。西北边是朝阳门。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_36]],["item1"]=[[2020qmjs1]],["left"]=[[fb36_35]],["name"]=[[东门]],["permission"]=2,["role1"]=[[fb36r36_1]],["role2"]=[[fb36r36_2]],["stepMusic"]=[[jiaobu]]},["fb36_37"]={["down"]=[[fb36_44]],["dsc"]=[[你走在巷道上，感到似乎有些不妙。南边仍是空荡荡的小道，见不到几个行人。东边是一家面馆。北边是白虎大道。一股阴风吹来，你禁不住打了个寒颤。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_37]],["name"]=[[杨柳胡同]],["permission"]=1,["right"]=[[fb36_38]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_31]]},["fb36_38"]={["dsc"]=[[这是一家价钱低廉的面馆，生意非常兴隆。外地游客多选择这里落脚，你可以在这里打听到各地的风土人情。穷人们也都喜欢来这里。店小二里里外外忙得团团转，接待着南腔北调的客人。几张脏乎乎的小木桌旁，坐满了各种各样的食客。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_38]],["item1"]=[[fb36item23]],["left"]=[[fb36_37]],["name"]=[[面馆]],["permission"]=2,["role1"]=[[fb36r38_1]],["stepMusic"]=[[jiaobu]]},["fb36_39"]={["down"]=[[fb36_54]],["dsc"]=[[这是一家药铺，一股浓浓的药味让你几欲窒息，那是从药柜上的几百个小抽屉里散发出来的。一位中年大夫在柜台后站着。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_39]],["item1"]=[[lylitem1]],["name"]=[[回春堂药店]],["permission"]=1,["role1"]=[[fb36r39_1]],["role2"]=[[fb36r39_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_32]]},["fb36_40"]={["dsc"]=[[这是一家简陋的打铁铺，中心摆着一个火炉，炉火把四周照得一片通红，你一走进去就感到浑身火热。墙角堆满了已完工和未完工的菜刀、铁锤、铁棍、匕首、护甲等物。一位铁匠满头大汗挥舞着铁锤，专心致志地在打铁。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_40]],["item1"]=[[duanzaoronglu1]],["name"]=[[打铁铺]],["permission"]=2,["role1"]=[[fb36r40_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_35]]},["fb36_41"]={["dsc"]=[[这是一家以买卖公平著称的当铺，一个五尺高的柜台挡在你的面前，柜台上摆着一个牌子，柜台后坐着贾老板，一双精明的眼睛上上下下打量着你。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_41]],["name"]=[[当铺]],["permission"]=2,["right"]=[[fb36_42]],["role1"]=[[fb36r41_1]],["stepMusic"]=[[jiaobu]]},["fb36_42"]={["down"]=[[fb36_46]],["dsc"]=[[这里是南大街。北边是白虎门广场，南边是南大街广场。西边是一家店铺，墙上写着一个大大的“当”字，仔细倾听，可以听到压低的讨价还价的声音。东边是一家小客店。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_42]],["left"]=[[fb36_41]],["name"]=[[南大街]],["permission"]=1,["right"]=[[fb36_43]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_33]]},["fb36_43"]={["dsc"]=[[这是一家价钱低廉的客栈，生意非常兴隆。据说全国各地都有这样的分店，而且所有的客栈都归一个人所有。不过他从来不露面，谁也不知道他究竟是怎样一个人。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_43]],["left"]=[[fb36_42]],["name"]=[[客店]],["permission"]=2,["role1"]=[[fb36r43_1]],["role2"]=[[fb36r43_2]],["role3"]=[[fb36r43_3]],["stepMusic"]=[[jiaobu]]},["fb36_44"]={["dsc"]=[[道上一个人也看不到，你突然有点害怕起来。东南边有一家棺材店。西南边是一条黑漆漆的小巷，你不知道要不要继续向里走。“还是往北回去吧，免得…”，心底里一个声音不住地对你说。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_44]],["leftDown"]=[[fb36_48]],["name"]=[[杨柳胡同]],["permission"]=1,["rightDown"]=[[fb36_49]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_37]]},["fb36_45"]={["dsc"]=[[这里是屠宰场，空气中弥漫着猪肉的气味。偶尔一阵热风吹过，顿时一股臭气袭来，直熏得人作呕。一个中年人手握屠刀，指挥着伙计们杀猪去毛。京城中屠宰场不计其数，但此处是最大的，据说宫里所有的猪肉都是从这里送去的。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_45]],["name"]=[[屠宰场]],["permission"]=2,["right"]=[[fb36_46]],["role1"]=[[fb36r45_1]],["role2"]=[[fb36item29]],["stepMusic"]=[[jiaobu]]},["fb36_46"]={["down"]=[[fb36_51]],["dsc"]=[[这里是一个人流滚滚的广场，也是京城里最热闹、最杂乱的地段。一座天桥横跨东西，正是卖杂货、变把戏、跑江湖杂人等聚居的所在。宽阔的大道向南北两头延伸。南边是永定门，通往郊外，北边是南大街，通往白虎门。东边是有名的“高升茶馆”，人们都爱在那儿休息聊天。西边有一家很大的屠宰场，不时传来猪凄厉的哀嚎。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_46]],["item1"]=[[fb36r46_4]],["item2"]=[[fb36fyb]],["item3"]=[[zjys]],["item4"]=[[zjys1]],["left"]=[[fb36_45]],["name"]=[[南大街广场]],["permission"]=1,["right"]=[[fb36_47]],["role1"]=[[fb36r46_1]],["role2"]=[[fb36r46_2]],["role3"]=[[fb36item25]],["role4"]=[[fb36r46_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_42]]},["fb36_47"]={["dsc"]=[[你一走进来，就闻到一股茶香沁入心脾，精神为之一爽。几张八仙桌一字排开，坐满了客人，或高声谈笑，或交头接耳。你要想打听江湖世故，这里是个好所在。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_47]],["left"]=[[fb36_46]],["name"]=[[高升茶馆]],["permission"]=1,["role1"]=[[fb36r47_1]],["role2"]=[[fb36r47_2]],["role3"]=[[fb36r47_3]],["stepMusic"]=[[jiaobu]]},["fb36_48"]={["down"]=[[fb36_50]],["dsc"]=[[这是一条十分僻静的小胡同，东南面有一家客店。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_48]],["name"]=[[杨柳胡同]],["permission"]=1,["rightUp"]=[[fb36_44]],["stepMusic"]=[[jiaobu]]},["fb36_49"]={["dsc"]=[[这是一家棺材店，一进门，一股楠木味扑鼻而来。屋子里很阴暗，桌子椅子都很破旧。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_49]],["item1"]=[[fb36item14]],["item2"]=[[fb36item15]],["item3"]=[[fb36item16]],["leftUp"]=[[fb36_44]],["name"]=[[棺材店]],["permission"]=2,["role1"]=[[fb36r49_1]],["stepMusic"]=[[jiaobu]]},["fb36_50"]={["dsc"]=[[这是一家客店，虽然价格低廉但墙壁已经开裂，屋顶正在漏雨。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_50]],["item1"]=[[fb36item8]],["item2"]=[[fb36item44]],["name"]=[[客店]],["permission"]=1,["role1"]=[[fb36r50_2]],["role2"]=[[fb36r50_3]],["role3"]=[[fb36r50_1c]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_48]]},["fb36_51"]={["dsc"]=[[这里是永定门，城门正上方刻着“永定门”三个大字，城墙上贴着几张官府告示。每天都有许多人从这里是出入京城，正因如此官兵盘查得格外仔细。一条笔直的大道向南北两边延伸。南边的驿道上人来车往，尘土飞扬。北边通往城中心。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb36_51]],["item1"]=[[fb36item47]],["name"]=[[永定门]],["permission"]=1,["role1"]=[[fb36r51_1]],["role2"]=[[fb36r51_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_46]]},["fb36_52"]={["dsc"]=[[位于棺材店之下的地窖，完全密闭的空间使得房间内无论有什么动静都不会有人察觉。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_52]],["item1"]=[[fb36item18]],["name"]=[[密室]],["permission"]=1,["role1"]=[[fb36r52_1]],["role2"]=[[fb36r52_2]],["role3"]=[[fb36r52_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb36_49]]},["fb36_53"]={["dsc"]=[[这里是平王府内的一座演武堂，当中挂着巨大的“武”字，地面铺着木板。许多身穿侍卫服饰的人在切磋武艺，其中也不乏江湖中人。]],["fightBackground"]=[[擂台]],["id"]=[[fb36_53]],["item1"]=[[fb36item36]],["left"]=[[fb36_03]],["name"]=[[平王内府]],["permission"]=2,["role1"]=[[fb36r53_2]],["role2"]=[[fb36r53_3]],["stepMusic"]=[[jiaobu]]},["fb36_54"]={["dsc"]=[[这里是回春堂的内室，用于给重症病患休息疗伤。内室摆设简单，只有一张木床，一把藤椅，和一个药柜。藤椅旁摆着一个石舂。室内有一股浓郁的药香味。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb36_54]],["name"]=[[药店内室]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb36_39]]}}0000000000